import{_ as a,o as i,c as r,ag as o}from"./chunks/framework.D7xI0JV8.js";const u=JSON.parse('{"title":"Compliance And Disclosure","description":"","frontmatter":{},"headers":[],"relativePath":"compliance-and-disclosure.md","filePath":"compliance-and-disclosure.md"}'),t={name:"compliance-and-disclosure.md"};function s(l,e,n,c,d,p){return i(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="compliance-and-disclosure" tabindex="-1">Compliance And Disclosure <a class="header-anchor" href="#compliance-and-disclosure" aria-label="Permalink to &quot;Compliance And Disclosure&quot;">​</a></h1><p>zkde.fi supports selective disclosure workflows that let users present scoped claims without exposing full strategy history.</p><h2 id="the-problem-this-solves" tabindex="-1">The Problem This Solves <a class="header-anchor" href="#the-problem-this-solves" aria-label="Permalink to &quot;The Problem This Solves&quot;">​</a></h2><p>Users and partner verifiers often need evidence of bounded behavior, but full account transparency can expose sensitive positioning, timing, or strategy details.</p><h2 id="why-this-matters" tabindex="-1">Why This Matters <a class="header-anchor" href="#why-this-matters" aria-label="Permalink to &quot;Why This Matters&quot;">​</a></h2><p>Selective disclosure creates a middle path: enough evidence to support operational checks, without forcing full public data disclosure.</p><h2 id="where-users-access-this-in-the-app" tabindex="-1">Where Users Access This In The App <a class="header-anchor" href="#where-users-access-this-in-the-app" aria-label="Permalink to &quot;Where Users Access This In The App&quot;">​</a></h2><ul><li><code>/profile?tab=compliance</code> for identity/compliance-oriented review</li><li><code>/agent?v=brain&amp;sub=pipeline</code> for workflow-oriented pipeline and disclosure context</li><li>legacy <code>sub=disclosure</code> links are mapped into supported Brain tabs by compatibility routing</li></ul><h2 id="core-api" tabindex="-1">Core API <a class="header-anchor" href="#core-api" aria-label="Permalink to &quot;Core API&quot;">​</a></h2><ul><li><code>GET /api/v1/zkdefi/compliance/profiles/{user_address}</code></li></ul><p>This endpoint returns compliance profile artifacts for the target Starknet address.</p><h2 id="data-flow" tabindex="-1">Data Flow <a class="header-anchor" href="#data-flow" aria-label="Permalink to &quot;Data Flow&quot;">​</a></h2><pre class="mermaid" data-mermaid-source="flowchart%20LR%0A%20%20U%5BUser%5D%20--%3E%20UI%5BProfile%20Compliance%20or%20Brain%20Pipeline%20UI%5D%0A%20%20UI%20--%3E%20API%5Bcompliance%2Fprofiles%20endpoint%5D%0A%20%20API%20--%3E%20S%5BBackend%20state%20and%20receipts%5D%0A%20%20S%20--%3E%20API%0A%20%20API%20--%3E%20UI">flowchart LR
  U[User] --&gt; UI[Profile Compliance or Brain Pipeline UI]
  UI --&gt; API[compliance/profiles endpoint]
  API --&gt; S[Backend state and receipts]
  S --&gt; API
  API --&gt; UI</pre><h2 id="problem-it-solves-in-practice" tabindex="-1">Problem It Solves In Practice <a class="header-anchor" href="#problem-it-solves-in-practice" aria-label="Permalink to &quot;Problem It Solves In Practice&quot;">​</a></h2><h3 id="for-users" tabindex="-1">For users <a class="header-anchor" href="#for-users" aria-label="Permalink to &quot;For users&quot;">​</a></h3><p>Allows users to share bounded claims without exposing complete transaction history.</p><h3 id="for-integrators" tabindex="-1">For integrators <a class="header-anchor" href="#for-integrators" aria-label="Permalink to &quot;For integrators&quot;">​</a></h3><p>Provides a structured integration point for compliance-adjacent checks and verifier dashboards.</p><h2 id="why-it-matters-operationally" tabindex="-1">Why It Matters Operationally <a class="header-anchor" href="#why-it-matters-operationally" aria-label="Permalink to &quot;Why It Matters Operationally&quot;">​</a></h2><p>Teams can separate “proof of claim context” from “full trade transparency,” which improves privacy posture while preserving useful verification signals.</p><h2 id="legal-boundary-important" tabindex="-1">Legal Boundary (Important) <a class="header-anchor" href="#legal-boundary-important" aria-label="Permalink to &quot;Legal Boundary (Important)&quot;">​</a></h2><p>This page describes product and API behavior only. It is not legal advice, not tax advice, and not investment advice. Availability of disclosure artifacts does not, by itself, guarantee regulatory sufficiency for any specific jurisdiction or use case.</p><h2 id="practical-guidance" tabindex="-1">Practical Guidance <a class="header-anchor" href="#practical-guidance" aria-label="Permalink to &quot;Practical Guidance&quot;">​</a></h2><p>If you are an integrator:</p><ol><li>Treat profile records as technical artifacts, not legal determinations.</li><li>Pair disclosure artifacts with your own policy and legal review process.</li><li>Keep jurisdiction-specific interpretation outside your API client logic.</li></ol><p>Next: <a href="/docs/risk-passport">Risk Passport</a> | <a href="/docs/profile-and-identity">Profile and identity</a> | <a href="/docs/api-overview">API overview</a></p><h2 id="key-fixtures-verified-2026-03-05" tabindex="-1">Key Fixtures (Verified 2026-03-05) <a class="header-anchor" href="#key-fixtures-verified-2026-03-05" aria-label="Permalink to &quot;Key Fixtures (Verified 2026-03-05)&quot;">​</a></h2><ul><li><code>GET /api/v1/zkdefi/compliance/profiles/{user_address}</code></li><li><code>GET /api/v1/zkdefi/risk_passport/v2/user/{address}</code></li><li><code>GET /api/v1/zkdefi/risk_profile/v2/{address}</code></li></ul>`,28)])])}const f=a(t,[["render",s]]);export{u as __pageData,f as default};
